// Added by Aman singh for new b2b bank transfer design
// UPDATED: beneficiary handling now reuses the SAME APIs as the DMT
// "Bank Transfer" page (reciptList / BENEFICIARYAdd / verificationBank /
// BENEFICIARYDelete / bankListApiwithid) instead of B2B's own separate
// APIs. Beneficiaries added/managed here are the exact same beneficiaries
// that show up on the DMT page — one shared list, one shared backend.
//
// FIX: api_id is no longer a hardcoded "bank1" string. Backend expects a
// real Mongo ObjectId (see error: "Cast to ObjectId failed for value
// 'bank1'"). We now fetch it dynamically via settingBank(), exactly like
// AddNewBeneficiary.jsx does with props?.initialCustomer?.api_id.

import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import {
  Box,
  Button,
  Grid,
  TextField,
  MenuItem,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Chip,
  Autocomplete,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import toastMessage from "../../utils/toastMessage";
import {
  B2BBankTransfer,
  reciptList,
  BENEFICIARYAdd,
  verificationBank,
  BENEFICIARYDelete,
  bankListApiwithid,
  settingBank,
  addBankDetail,
} from "../../api/login/Login";

const TRANSFER_MODES = ["IMPS", "NEFT"];

const B2BBankTransferPage = () => {
  const location = useLocation();
  const activeWallet = location?.state?.walletType || "MAIN";
  // ✅ Dynamic bank ObjectId — NO hardcoded "bank1" guess anymore.
  // Matches DMT's NewBankTransfer.jsx pattern exactly: fetch the full
  // bank list + defaultApi, let the user pick which bank they're
  // actually onboarded on (defaultApi may not be the one you're
  // onboarded on — that's what caused "You are not onboard on Bank3").
  const [allBank, setAllBank] = useState([]);
  const [apiId, setApiId] = useState(null);
  const [apiIdLoading, setApiIdLoading] = useState(true);

  useEffect(() => {
    const fetchBankId = async () => {
      try {
        const res = await settingBank();
        const banks = res?.data?.data?.dmtApiType || [];
        setAllBank(banks);
        // Pre-select the default bank, but user can change it below.
        setApiId(res?.data?.data?.defaultApi || banks[0]?._id || null);
      } catch (error) {
        toastMessage(true, "Unable to load bank settings");
      } finally {
        setApiIdLoading(false);
      }
    };
    fetchBankId();
  }, []);

  // Step 1 — Mobile / Customer
  const [searchMobile, setSearchMobile] = useState("");
  const [searchLoading, setSearchLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [savedBeneficiaries, setSavedBeneficiaries] = useState([]);

  // Selected beneficiary + transfer
  const [selectedBeneficiary, setSelectedBeneficiary] = useState(null);
  const [transferMode, setTransferMode] = useState("");
  const [amount, setAmount] = useState("");
  const [loading, setLoading] = useState(false);

  // TPIN
  const [openTpin, setOpenTpin] = useState(false);
  const [tpin, setTpin] = useState("");

  // Add Beneficiary Dialog
  const [openAddDialog, setOpenAddDialog] = useState(false);
  const [bankList, setBankList] = useState([]);
  const [addLoading, setAddLoading] = useState(false);
  const [newBeneficiary, setNewBeneficiary] = useState({
    name: "",
    bankId: "",       // dropdown's selected value = bank._id (used for the Select control)
    bankCode: "",     // bank.bankID — short vendor code, sent separately
    ifsc: "",
    account_number: "",
    confirm_account_number: "",
  });

  // OTP verification (mirrors DMT's AddNewBeneficiaryPage flow — some
  // vendors return statusCode 201 asking for mobile OTP before the
  // beneficiary becomes usable)
  const [openOtpDialog, setOpenOtpDialog] = useState(false);
  const [otpRecipientId, setOtpRecipientId] = useState("");
  const [otp, setOtp] = useState("");
  const [otpLoading, setOtpLoading] = useState(false);

  // ---------------- Search Mobile (DMT: reciptList) ----------------
  const handleSearchBeneficiary = async () => {
    if (!apiId) {
      toastMessage(true, "Bank settings loading, please wait...");
      return;
    }
    if (!searchMobile || searchMobile.length < 10) {
      toastMessage(true, "Enter valid mobile number");
      return;
    }
    try {
      setSearchLoading(true);
      setSearched(false);
      setSelectedBeneficiary(null);
      const res = await reciptList({ mobile: searchMobile, api_id: apiId }); // ✅ apiId
      const data = res?.data?.data;
      // ✅ Backend sends `data: {}` (an object, not array) on error
      // responses like "You are not onboard on BankX" — `{} || []`
      // stays `{}` since objects are truthy, which crashed .map() below.
      // Guard with Array.isArray so we always end up with a real array.
      if (res?.data?.error) {
        setSavedBeneficiaries([]);
        toastMessage(true, res?.data?.message || "Unable to fetch beneficiaries");
      } else {
        setSavedBeneficiaries(Array.isArray(data) ? data : []);
      }
      setSearched(true);
    } catch (error) {
      setSavedBeneficiaries([]);
      setSearched(true);
      toastMessage(true, error?.response?.data?.message || "Search failed");
    } finally {
      setSearchLoading(false);
    }
  };

  // ---------------- Add Beneficiary Dialog ----------------
  const openAddBeneficiaryDialog = async () => {
    if (!apiId) {
      toastMessage(true, "Bank settings loading, please wait...");
      return;
    }
    setOpenAddDialog(true);
    if (bankList.length === 0) {
      try {
        // DMT: bankListApiwithid — returns { bank_name, ifsc_code, bankID (short code), _id (real ObjectId), ... }
        const res = await bankListApiwithid(apiId); // ✅ apiId
        const data =
          res?.data?.data?.map((item) => ({
            ...item,
            label: item.bank_name,
            value: item._id, // ✅ use the real ObjectId as the dropdown value
          })) || [];
        setBankList(data);
      } catch (error) {
        toastMessage(true, "Unable to load bank list");
      }
    }
  };

  const handleBankChange = (selectedId) => {
    // ✅ match by _id (the real ObjectId), not bankID
    const bank = bankList.find((b) => b._id === selectedId);
    setNewBeneficiary((prev) => ({
      ...prev,
      bankId: bank?._id || selectedId,   // real ObjectId → backend's `bank_id`
      bankCode: bank?.bankID || "",       // short vendor code → backend's `bank_code`
      // auto-fill IFSC if bank record has one; user can still edit it
      ifsc: bank?.ifsc_code || bank?.bank_ifsc || prev.ifsc,
    }));
  };

  const resetAddForm = () => {
    setNewBeneficiary({
      name: "",
      bankId: "",
      bankCode: "",
      ifsc: "",
      account_number: "",
      confirm_account_number: "",
    });
  };

  // skipVerify = true  → "Add Without Verify" (isVerified: false, no bank-verify call)
  // skipVerify = false → "Verify & Add" (calls DMT's verificationBank first)
  const submitAddBeneficiary = async (skipVerify) => {
    if (!apiId) {
      toastMessage(true, "Bank settings loading, please wait...");
      return;
    }

    const { name, bankId, bankCode, ifsc, account_number, confirm_account_number } =
      newBeneficiary;

    if (!name || !bankId || !ifsc || !account_number || !confirm_account_number) {
      toastMessage(true, "Please fill all fields");
      return;
    }
    if (account_number !== confirm_account_number) {
      toastMessage(true, "Account number and confirm account number must match");
      return;
    }

    try {
      setAddLoading(true);

      // Optional verify step before adding — DMT: verificationBank
      if (!skipVerify) {
        const verifyRes = await verificationBank({
          name,
          ifsc,
          bankAccount: account_number,
          phone: searchMobile,
        });
        if (verifyRes?.data?.error) {
          toastMessage(true, verifyRes?.data?.message || "Verification failed");
          setAddLoading(false);
          return;
        }
      }

      // DMT: BENEFICIARYAdd payload shape (bank_id = real ObjectId, bank_code = short vendor code)
      const payload = {
        recipient_name: name,
        customer_mobile: searchMobile,
        account_number,
        ifsc,
        bank_id: bankId,     // ✅ real Mongo ObjectId
        bank_code: bankCode, // ✅ short vendor code (bankID)
        recipient_mobile: searchMobile,
        isVerified: !skipVerify,
        api_id: apiId, // ✅ apiId
        user_id: window.localStorage.getItem("userIdToken"),
      };
      const res = await BENEFICIARYAdd(payload);

      if (res?.data?.statusCode === 201) {
        // Vendor requires mobile OTP before beneficiary is usable
        setOtpRecipientId(res?.data?.data?.recipient_id);
        setOpenAddDialog(false);
        resetAddForm();
        setOpenOtpDialog(true);
        toastMessage(false, res?.data?.message || "OTP sent");
      } else if (res?.data?.statusCode === 200) {
        toastMessage(false, res?.data?.message || "Beneficiary added successfully");
        setOpenAddDialog(false);
        resetAddForm();
        handleSearchBeneficiary();
      } else {
        toastMessage(true, res?.data?.message || "Failed to add beneficiary");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Failed to add beneficiary");
    } finally {
      setAddLoading(false);
    }
  };

  // ---------------- OTP verify (DMT: veryOtpaddbene) ----------------
  const handleOtpVerify = async () => {
    if (otp.length < 6) return;
    setOtpLoading(true);
    try {
      const { veryOtpaddbene } = await import("../../api/login/Login");
      const res = await veryOtpaddbene({
        recipient_id: otpRecipientId,
        customer_mobile: searchMobile,
        otp,
      });
      if (res?.data?.statusCode == 200) {
        toastMessage(false, res?.data?.message || "Beneficiary verified");
        setOpenOtpDialog(false);
        setOtp("");
        setOtpRecipientId("");
        handleSearchBeneficiary();
      } else {
        toastMessage(true, res?.data?.message || "OTP verification failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "OTP verification failed");
    } finally {
      setOtpLoading(false);
    }
  };

  // ---------------- Select / Delete Beneficiary ----------------
  const handleSelect = (beneficiary) => {
    setSelectedBeneficiary(beneficiary);
    setAmount("");
    setTransferMode("");
  };

  // DMT: BENEFICIARYDelete
  const handleDelete = async (recipientId) => {
    if (!apiId) {
      toastMessage(true, "Bank settings loading, please wait...");
      return;
    }
    try {
      const res = await BENEFICIARYDelete({
        customer_mobile: searchMobile,
        recipient_id: recipientId,
        api_id: apiId, // ✅ apiId
        user_id: window.localStorage.getItem("userIdToken"),
      });
      if (res?.data?.statusCode == 200) {
        toastMessage(false, "Beneficiary deleted");
        if (selectedBeneficiary?.recipient_id === recipientId) {
          setSelectedBeneficiary(null);
        }
        handleSearchBeneficiary();
      } else {
        toastMessage(true, res?.data?.message || "Delete failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Delete failed");
    }
  };

  // ---------------- Submit Payout (UNCHANGED — still B2B's own transfer API) ----------------
  const handleSubmitClick = () => {
    if (!selectedBeneficiary) {
      toastMessage(true, "Select a beneficiary first");
      return;
    }
    if (!transferMode) {
      toastMessage(true, "Select transfer mode");
      return;
    }
    if (!amount || Number(amount) <= 0) {
      toastMessage(true, "Enter valid amount");
      return;
    }
    setOpenTpin(true);
  };

  const submitPayout = async () => {
    if (!/^\d{4}$/.test(tpin)) {
      toastMessage(true, "Invalid TPIN");
      return;
    }
    try {
      setLoading(true);
      const payload = {
        transfer_mode: transferMode,
        bank_account_number: selectedBeneficiary.account,
        bank_ifsc: selectedBeneficiary.ifsc,
        beneficiary_name: selectedBeneficiary.recipient_name,
        beneficiary_account_name: selectedBeneficiary.bank,
        beneficiary_mobile: selectedBeneficiary.recipient_mobile || searchMobile,
        beneficiary_account_type: "SAVINGS",
        transfer_amount: Number(amount),
        tpin,
        wallet_type: activeWallet,
      };
      const res = await B2BBankTransfer(payload);
      if (res?.data?.success) {
        toastMessage(false, res.data.message || "Payout Successful");
        setOpenTpin(false);
        setTpin("");
        setAmount("");
        setTransferMode("");
        setSelectedBeneficiary(null);
      } else {
        toastMessage(true, res?.data?.message || "Payout Failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Server error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box p={3} bgcolor="#fff" borderRadius={2}>
      {/* <Typography variant="h6" mb={2}>
        B2B Bank Transfer
      </Typography> */}
      <Typography variant="h6" mb={2}>
        Send to Own Other Bank
      </Typography>

      {/* Bank selector — pick the vendor bank you're actually onboarded on.
          The backend rejects api_id values you aren't onboarded on
          (e.g. "You are not onboard on Bank3"), so don't silently trust
          defaultApi — let the user confirm/change it. */}
      {/* <Box sx={{ mb: 3, maxWidth: 320 }}>
        <TextField
          select
          fullWidth
          size="small"
          label="Transfer Through"
          value={apiId || ""}
          disabled={apiIdLoading || allBank.length === 0}
          onChange={(e) => {
            setApiId(e.target.value);
            // Selected bank changed — any previous search results are stale.
            setSearched(false);
            setSavedBeneficiaries([]);
            setSelectedBeneficiary(null);
          }}
        >
          {allBank.length === 0 && (
            <MenuItem value="" disabled>
              {apiIdLoading ? "Loading banks..." : "No banks available"}
            </MenuItem>
          )}
          {allBank.map((bank) => (
            <MenuItem key={bank._id} value={bank._id}>
              {bank.name?.toUpperCase()}
            </MenuItem>
          ))}
        </TextField>
      </Box> */}

      {/* Step 1: Mobile Number */}
      <Box sx={{ display: "flex", gap: 2, alignItems: "center", mb: 3 }}>
        {/* <TextField
          size="small"
          label="Remitter / Mobile Number"
          value={searchMobile}
          disabled={searchLoading}
          onChange={(e) => setSearchMobile(e.target.value)}
        /> */}
        <TextField
          size="small"
          label="Remitter / Mobile Number"
          value={searchMobile}
          disabled={searchLoading}
          inputProps={{ maxLength: 10, inputMode: "numeric" }}
          onChange={(e) => {
            const onlyDigits = e.target.value.replace(/\D/g, "");
            if (onlyDigits.length <= 10) setSearchMobile(onlyDigits);
          }}
        />
        <Button
          variant="contained"
          onClick={handleSearchBeneficiary}
          disabled={searchLoading || apiIdLoading || !apiId} // ✅ block until a bank is selected
        >
          {searchLoading
            ? "Checking..."
            : apiIdLoading
              ? "Loading..."
              : "Proceed"}
        </Button>
      </Box>

      {searched && (
        <Grid container spacing={3}>
          {/* Left: Beneficiary List */}
          <Grid item xs={12} md={7}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                mb: 1.5,
              }}
            >
              <Typography variant="subtitle1" fontWeight={600}>
                Beneficiary List
              </Typography>
              <Button
                size="small"
                variant="contained"
                color="success"
                onClick={openAddBeneficiaryDialog}
              >
                + Add Beneficiary
              </Button>
            </Box>

            {savedBeneficiaries.length === 0 && (
              <Typography variant="body2" color="text.secondary">
                No beneficiary found. Add a new one to get started.
              </Typography>
            )}

            {savedBeneficiaries.map((beni) => {
              const isSelected =
                selectedBeneficiary?.recipient_id === beni.recipient_id;
              return (
                <Box
                  key={beni.recipient_id}
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    p: 1.5,
                    mb: 1,
                    border: isSelected ? "2px solid #2e7d32" : "1px solid #e5e7eb",
                    borderRadius: 1.5,
                  }}
                >
                  <Box>
                    <Typography variant="body2" fontWeight={600}>
                      {beni.recipient_name}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" display="block">
                      {beni.bank}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {beni.account} · {beni.ifsc}
                    </Typography>
                  </Box>
                  <Box sx={{ display: "flex", gap: 1, alignItems: "center" }}>
                    {isSelected ? (
                      <Chip
                        icon={<CheckCircleIcon />}
                        label="Selected"
                        color="success"
                        size="small"
                      />
                    ) : (
                      <Button
                        size="small"
                        variant="contained"
                        onClick={() => handleSelect(beni)}
                      >
                        Select
                      </Button>
                    )}
                    <IconButton
                      size="small"
                      color="error"
                      onClick={() => handleDelete(beni.recipient_id)}
                    >
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  </Box>
                </Box>
              );
            })}
          </Grid>

          {/* Right: Transfer Panel */}
          <Grid item xs={12} md={5}>
            <Box sx={{ p: 2, border: "1px solid #e5e7eb", borderRadius: 2 }}>
              <Typography variant="subtitle1" fontWeight={600} mb={2}>
                Transfer Fund
              </Typography>

              {!selectedBeneficiary ? (
                <Typography variant="body2" color="text.secondary">
                  Select a beneficiary from the list to send money.
                </Typography>
              ) : (
                <>
                  <Typography variant="body2" mb={2}>
                    Sending to: <b>{selectedBeneficiary.recipient_name}</b>
                  </Typography>

                  <TextField
                    select
                    fullWidth
                    size="small"
                    label="Transfer Mode"
                    value={transferMode}
                    disabled={loading}
                    onChange={(e) => setTransferMode(e.target.value)}
                    sx={{ mb: 2 }}
                  >
                    {TRANSFER_MODES.map((mode) => (
                      <MenuItem key={mode} value={mode}>
                        {mode}
                      </MenuItem>
                    ))}
                  </TextField>

                  <TextField
                    fullWidth
                    size="small"
                    type="number"
                    label="Amount"
                    value={amount}
                    disabled={loading}
                    onChange={(e) => setAmount(e.target.value)}
                    sx={{ mb: 2 }}
                  />

                  <Button
                    fullWidth
                    variant="contained"
                    onClick={handleSubmitClick}
                    disabled={loading}
                  >
                    {loading ? "Processing..." : "Submit"}
                  </Button>
                </>
              )}
            </Box>
          </Grid>
        </Grid>
      )}

      {/* Add Beneficiary Dialog */}
      <Dialog open={openAddDialog} onClose={() => setOpenAddDialog(false)} fullWidth maxWidth="xs">
        <DialogTitle>Add New Beneficiary</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} mt={0.5}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                size="small"
                label="Beneficiary Name"
                value={newBeneficiary.name}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({ ...prev, name: e.target.value }))
                }
              />
            </Grid>
            {/* <Grid item xs={12}>
              <TextField
                select
                fullWidth
                size="small"
                label="Select Bank"
                value={newBeneficiary.bankId}
                onChange={(e) => handleBankChange(e.target.value)}
              >
                {bankList.map((bank) => (
                  <MenuItem key={bank._id} value={bank._id}>
                    {bank.bank_name}
                  </MenuItem>
                ))}
              </TextField>
            </Grid> */}
            {/* <Grid item xs={12}>
              <Autocomplete
                fullWidth
                size="small"
                options={bankList}
                getOptionLabel={(bank) => bank.bank_name || ""}
                value={bankList.find((b) => b._id === newBeneficiary.bankId) || null}
                onChange={(e, selectedBank) =>
                  handleBankChange(selectedBank?._id || "")
                }
                isOptionEqualToValue={(option, value) => option._id === value._id}
                renderInput={(params) => (
                  <TextField {...params} label="Select Bank" placeholder="Type to search..." />
                )}
              />
            </Grid> */}
            <Grid item xs={12}>
              <Autocomplete
                fullWidth
                size="small"
                freeSolo
                options={bankList}
                // getOptionLabel={(bank) =>
                //   typeof bank === "string" ? bank : bank.bank_name || ""
                // }
                getOptionLabel={(bank) =>
                  typeof bank === "string"
                    ? bank.toUpperCase()
                    : (bank.bank_name || "").toUpperCase()
                }
                // filterOptions={(options, params) => {
                //   const filtered = options.filter((opt) =>
                //     opt.bank_name?.toLowerCase().includes(params.inputValue.toLowerCase())
                //   );
                //   if (params.inputValue !== "" && filtered.length === 0) {
                //     filtered.push({
                //       _id: "__add_new__",
                //       bank_name: `Add "${params.inputValue}" as new bank`,
                //       inputValue: params.inputValue,
                //     });
                //   }
                //   return filtered;
                // }}
                filterOptions={(options, params) => {
                  const filtered = options.filter((opt) =>
                    opt.bank_name?.toLowerCase().includes(params.inputValue.toLowerCase())
                  );
                  if (params.inputValue !== "" && filtered.length === 0) {
                    filtered.push({
                      _id: "__add_new__",
                      bank_name: `Add "${params.inputValue.toUpperCase()}" as new bank`,
                      inputValue: params.inputValue,
                    });
                  }
                  return filtered;
                }}
                value={bankList.find((b) => b._id === newBeneficiary.bankId) || null}
                onChange={async (e, selectedBank) => {
                  if (!selectedBank) {
                    handleBankChange("");
                    return;
                  }
                  if (selectedBank._id === "__add_new__") {
                    try {
                      // const res = await addBankDetail({
                      //   list: [
                      //     {
                      //       bank_name: selectedBank.inputValue,
                      //       ifsc_code: "",
                      //     },
                      //   ],
                      // });
                      const res = await addBankDetail({
                        list: [
                          {
                            bank_name: selectedBank.inputValue.trim().toUpperCase(),
                            ifsc_code: "",
                          },
                        ],
                      });
                      if (res?.data?.status_Code === "200" && res?.data?.data?.length) {
                        const newBank = res.data.data[0];
                        setBankList((prev) => [...prev, newBank]);
                        handleBankChange(newBank._id);
                        toastMessage(false, "New bank added successfully");
                      } else {
                        toastMessage(true, res?.data?.message || "Failed to add bank");
                      }
                    } catch (err) {
                      toastMessage(true, err?.response?.data?.message || "Failed to add bank");
                    }
                    return;
                  }
                  handleBankChange(selectedBank._id || "");
                }}
                isOptionEqualToValue={(option, value) => option._id === value._id}
                renderInput={(params) => (
                  <TextField {...params} label="Select Bank" placeholder="Type to search..." />
                )}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                size="small"
                label="IFSC Code"
                value={newBeneficiary.ifsc}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({
                    ...prev,
                    ifsc: e.target.value.toUpperCase(),
                  }))
                }
              />
              <Typography variant="caption" color="primary">
                Master IFSC auto-filled. You can change this if required.
              </Typography>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                size="small"
                label="Beneficiary Account Number"
                value={newBeneficiary.account_number}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({
                    ...prev,
                    account_number: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                size="small"
                label="Confirm Account Number"
                value={newBeneficiary.confirm_account_number}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({
                    ...prev,
                    confirm_account_number: e.target.value,
                  }))
                }
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions sx={{ flexDirection: "column", gap: 1, px: 3, pb: 2 }}>
          <Box sx={{ display: "flex", gap: 1, width: "100%" }}>
            <Button
              fullWidth
              variant="contained"
              color="error"
              disabled={addLoading}
              onClick={() => submitAddBeneficiary(false)}
            >
              {addLoading ? "..." : "Verify & Add"}
            </Button>
            <Button
              fullWidth
              variant="outlined"
              color="inherit"
              disabled={addLoading}
              onClick={() => submitAddBeneficiary(true)}
            >
              Add Without Verify
            </Button>
          </Box>
          <Button fullWidth onClick={() => setOpenAddDialog(false)} disabled={addLoading}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>

      {/* OTP Verification Dialog (mirrors DMT's flow — only appears if the
          vendor responds with statusCode 201 asking for OTP) */}
      <Dialog open={openOtpDialog} onClose={() => setOpenOtpDialog(false)} maxWidth="xs" fullWidth>
        <DialogTitle>OTP Verification</DialogTitle>
        <DialogContent>
          <Typography mb={2}>
            Enter the 6-digit code sent to the customer's mobile number.
          </Typography>
          <TextField
            fullWidth
            label="Enter OTP"
            value={otp}
            onChange={(e) => {
              const onlyDigits = e.target.value.replace(/\D/g, "");
              if (onlyDigits.length <= 6) setOtp(onlyDigits);
            }}
            inputProps={{ maxLength: 6 }}
            autoFocus
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenOtpDialog(false)} disabled={otpLoading}>
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={handleOtpVerify}
            disabled={otp.length < 6 || otpLoading}
          >
            {otpLoading ? "Verifying..." : "Verify"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* TPIN Dialog */}
      <Dialog open={openTpin} onClose={() => setOpenTpin(false)}>
        <DialogTitle align="center">Enter TPIN</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            type="password"
            value={tpin}
            disabled={loading}
            inputProps={{ maxLength: 4 }}
            onChange={(e) =>
              /^\d{0,4}$/.test(e.target.value) && setTpin(e.target.value)
            }
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenTpin(false)} disabled={loading}>
            Cancel
          </Button>
          <Button onClick={submitPayout} disabled={loading}>
            {loading ? "Processing..." : "Confirm"}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default B2BBankTransferPage;
